package com.example

/**
 * 💡 Extensive Curated Flashcard Bank for Edu.LK
 * Provides 100% curriculum-accurate, non-repeating flashcard questions across all 15 sets.
 * Guarantees that every card in every set is unique, relevant to that set's unit theme,
 * and directly aligned with the G.C.E. O/L syllabus.
 */
object FlashcardCuratedBank {

  data class FlashcardContent(
    val question: String,
    val answer: String,
    val tip: String,
    val fact: String
  )

  fun getCard(
    grade: String,
    subject: String,
    setNum: Int,
    cardInSet: Int,
    unitTheme: String
  ): FlashcardContent {
    val cleanTheme = unitTheme.substringAfter(". ").trim()

    return when {
      subject.contains("විද්‍යාව") -> getScienceCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("ගණිතය") -> getMathCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("ඉතිහාසය") -> getHistoryCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("බුද්ධ") || subject.contains("ආගම") -> getBuddhismCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("සිංහල") -> getSinhalaCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("English") || subject.contains("ඉංග්‍රීසි") -> getEnglishCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("පුරවැසි") -> getCivicsCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("වාණිජ") || subject.contains("ගිණුම්") -> getCommerceCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("ICT") || subject.contains("තොරතුරු") -> getIctCard(grade, setNum, cardInSet, cleanTheme)
      subject.contains("භූගෝල") -> getGeographyCard(grade, setNum, cardInSet, cleanTheme)
      else -> getGeneralCard(grade, subject, setNum, cardInSet, cleanTheme)
    }
  }

  // --------------------------------------------------------------------------
  // 1. SCIENCE FLASHCARDS (300 Distinct Questions across 15 Sets)
  // --------------------------------------------------------------------------
  private fun getScienceCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val scienceTopics = mapOf(
      1 to listOf( // ජීවයේ රසායනික පදනම
        FlashcardContent("කාබෝහයිඩ්‍රේටවල මූලද්‍රව්‍ය සංයුතිය සහ අනුපාතය කුමක්ද?", "කාබන් (C), හයිඩ්‍රජන් (H) සහ ඔක්සිජන් (O). H:O අනුපාතය 2:1 වේ.", "ග්ලූකෝස් සූත්‍රය C₆H₁₂O₆ වේ.", "C : H : O = 1 : 2 : 1"),
        FlashcardContent("ප්‍රෝටීනවල තැනුම් ඒකකය කුමක්ද? එහි ඇති රසායනික බන්ධනය කුමක්ද?", "ඇමයිනෝ අම්ල. ඇමයිනෝ අම්ල එකිනෙක බැඳෙන්නේ පෙප්ටයිඩ බන්ධන (Peptide bonds) මගිනි.", "ප්‍රෝටීනවල C, H, O, N අනිවාර්යයෙන් ද බොහෝවිට S ද අඩංගු වේ.", "ඇමයිනෝ අම්ල 20ක් ඇත"),
        FlashcardContent("ග්ලූකෝස් හඳුනාගැනීමේ රසායනික පරීක්ෂාව කුමක්ද? නිරීක්ෂණය කුමක්ද?", "බෙනඩික්ට් පරීක්ෂාව (Benedict's Test). ජල තාපකයක රත් කළ විට නිල් පැහැයේ සිට ගඩොල් රතු අවක්ෂේපයක් ලැබේ.", "සුක්‍රෝස් (මේස සීනි) ඔක්සිහාරක නොවන සීනි බැවින් සෘජුවම බෙනඩික්ට් පරීක්ෂාවට රතු පැහැ නොදෙයි.", "ගඩොල් රතු අවක්ෂේපය"),
        FlashcardContent("පිෂ්ඨය හඳුනාගැනීමට යොදාගන්නා ද්‍රාවණය කුමක්ද? නිරීක්ෂණය කුමක්ද?", "අයඩින් ද්‍රාවණය (Iodine solution). පිෂ්ඨය ඇති විට දුඹුරු පැහැ අයඩින් තද නිල්/කළු පැහැයට හැරේ.", "අල, බත්, පාන් ආදියෙහි පිෂ්ඨය බහුලව පවතී.", "අයඩින් → තද නිල්"),
        FlashcardContent("ප්‍රෝටීන හඳුනාගැනීමේ පරීක්ෂාව සහ නිරීක්ෂණය කුමක්ද?", "බයියුරෙට් පරීක්ෂාව (Biuret Test). ලා නිල් පැහැ ද්‍රාවණයට NaOH හා CuSO₄ දැමූ විට දම්/රෝස පැහැයක් ලැබේ.", "බිත්තර සුදුමදය හෝ සෝයා කිරි මේ සඳහා පහසුවෙන් යොදාගත හැක.", "බයියුරෙට් → දම් පැහැය"),
        FlashcardContent("ලිපිඩ හඳුනාගැනීමට යොදාගන්නා පරීක්ෂණ 2ක් නම් කරන්න.", "1. සුඩාන් III පරීක්ෂාව (රතු තට්ටුවක් වෙන්වීම).\n2. සුදු කඩදාසි පරීක්ෂාව (පාරභාසක පැල්ලමක් ඇතිවීම).", "ලිපිඩ ජලයේ අද්‍රාව්‍ය වන අතර කාබනික ද්‍රාවකවල ද්‍රාව්‍ය වේ.", "ට්‍රයිග්ලිසරයිඩ = ග්ලිසරෝල් + මේද අම්ල 3"),
        FlashcardContent("විටමින් C ඌනතාවයෙන් ඇතිවන රෝගය සහ රෝග ලක්ෂණ මොනවාද?", "ස්කර්වි (Scurvy) රෝගය. විදුරුමහෙන් ලේ ගැලීම, තුවාල සුවවීම ප්‍රමාද වීම සහ ප්‍රතිශක්තිය දුර්වල වීම.", "දෙහි, දොඩම්, නෙල්ලි සහ පේර විටමින් C බහුල ප්‍රභව වේ.", "විටමින් C = ඇස්කෝබික් අම්ලය"),
        FlashcardContent("විටමින් A ඌනතාවය නිසා ඇතිවන ආබාධය කුමක්ද?", "රාත්‍රී අන්ධතාවය (Night blindness) සහ ඇසේ වියළි බව (සෙරොෆ්තැල්මියාව).", "කැරට්, කහ පැහැති පලතුරු, නිවිති සහ පීකුදු විටමින් A බහුල ආහාරයි.", "රෙටිනෝල් (Retinol)"),
        FlashcardContent("විටමින් D සහ කැල්සියම් ඌනතාවයෙන් දරුවන්ට හා වැඩිහිටියන්ට වැළඳෙන රෝග මොනවාද?", "ළමුන්ට: රිකට්සියාව (Rickets - ඇදවුණු අස්ථි).\nවැඩිහිටියන්ට: ඔස්ටියෝමලේෂියාව (Osteomalacia) සහ ඔස්ටියෝපොරෝසිස්.", "උදෑසන හිරු එළියට නිරාවරණය වීමෙන් සිරුරේ විටමින් D නිපදවේ.", "Ca & Vit D = අස්ථි ශක්තිමත් කරයි"),
        FlashcardContent("යකඩ (Fe) ඌනතාවය නිසා ඇතිවන රෝගය කුමක්ද?", "රක්තහීනතාවය (Anaemia). රුධිරයේ හිමොග්ලොබින් මට්ටම අඩුවීමෙන් ක්ලාන්තය හා අධික මහන්සිය ඇතිවේ.", "පීකුදු, තද කොළ පැහැ එළවළු සහ මස් වර්ග යකඩ බහුල ආහාරයි.", "හිමොග්ලොබින්හි කේන්ද්‍රීය ලෝහය Fe වේ"),
        FlashcardContent("අයඩින් (I) ඌනතාවයෙන් වැළඳෙන තත්වයන් මොනවාද?", "ගලගණ්ඩය (Goitre - තයිරොයිඩ් ග්‍රන්ථිය ඉදිමීම) සහ කුඩා දරුවන්ගේ මානසික/කායික වර්ධන ඌනතා (ක්‍රෙටිනිස්මය).", "අයඩීකෘත ලුණු සහ මුහුදු ආහාර මගින් අයඩින් ඌනතාව වළක්වා ගත හැක.", "තයිරොක්සින් හෝමෝනයට I අත්‍යවශ්‍යයි"),
        FlashcardContent("ජලයේ ඇති ඉහළ විශිෂ්ට තාප ධාරිතාවේ ජෛව විද්‍යාත්මක වැදගත්කම කුමක්ද?", "ජීවීන්ගේ සිරුරේ අභ්‍යන්තර උෂ්ණත්වය එකවර ක්ෂණිකව වෙනස් නොවී නියතව පවත්වා ගැනීමට ඉවහල් වීම.", "ජලයේ විශිෂ්ට තාප ධාරිතාව 4200 J kg⁻¹ K⁻¹ කි.", "ජීවී දේහයෙන් 70%ක් පමණ ජලයයි"),
        FlashcardContent("ඩී.එන්.ඒ. (DNA) අණුවේ නියුක්ලියෝටයිඩයක අඩංගු සංඝටක 3 මොනවාද?", "1. ඩිඔක්සිරයිබෝස් ඩියොක්සි සීනි\n2. නයිට්‍රජනීය භෂ්මයක් (A, T, G, C)\n3. පොස්පේට් කාණ්ඩයක්", "DNA යනු ද්විත්ව හෙලික්සීය ව්‍යුහයකි.", "A-T (ද්විත්ව බන්ධන), G-C (ත්‍රිත්ව බන්ධන)"),
        FlashcardContent("ආර්.එන්.ඒ. (RNA) සහ DNA අතර ඇති ප්‍රධාන වෙනස්කම් 2ක් දක්වන්න.", "1. RNA හි රයිබෝස් සීනි ඇති අතර DNA හි ඩිඔක්සිරයිබෝස් සීනි ඇත.\n2. RNA හි තයිමින් (T) වෙනුවට යුරැසිල් (U) භෂ්මය පවතී.", "RNA තනි පොලිනියුක්ලියෝටයිඩ දාමයකි.", "RNA: A, U, G, C"),
        FlashcardContent("ජීවී දේහ තුළ ජලයේ ඇති ඉහළ වාෂ්පීකරණයේ ගුප්ත තාපයේ වැදගත්කම කුමක්ද?", "දහඩිය දැමීමේදී සිරුරෙන් සුළු ජල ප්‍රමාණයක් වාෂ්පීකරණය වීමෙන් විශාල තාප ප්‍රමාණයක් ඉවත් වී සිසිලනය ඇතිවීම.", "ශාකවල උත්ස්වේදනය මඟින් පත්‍ර සිසිල් කිරීමට ද මෙය ඉවහල් වේ.", "වාෂ්පීකරණ ගුප්ත තාපය = 2.26 × 10⁶ J kg⁻¹"),
        FlashcardContent("එන්සයිම (Enzymes) යනු මොනවාද? ඒවායේ රසායනික ස්වභාවය කුමක්ද?", "ජෛව රසායනික ප්‍රතික්‍රියා සීඝ්‍ර කරන ජෛව උත්ප්‍රේරක වේ. සියලුම එන්සයිම ප්‍රෝටීන වේ.", "එන්සයිම ප්‍රතික්‍රියාවේ සක්‍රියන ශක්තිය (Activation Energy) අඩු කරයි.", "උෂ්ණත්වය 40°C ඉක්මවූ විට එන්සයිම විකෘති වේ"),
        FlashcardContent("මොනොසැකරයිඩ සඳහා උදාහරණ 3ක් දක්වන්න.", "ග්ලූකෝස් (පලතුරු/රුධිරයේ), ෆෲක්ටෝස් (මී පැණි/පලතුරුවල), ගැලැක්ටෝස් (කිරි සීනිවල).", "මේවා සරලම කාබෝහයිඩ්‍රේට වන අතර ජලයේ ද්‍රාව්‍ය පැණි රසැති ස්ඵටික වේ.", "අණුක සූත්‍රය C₆H₁₂O₆ වේ"),
        FlashcardContent("ඩයිසැකරයිඩ 3 සහ ඒවා සෑදෙන ඒකක මොනවාද?", "1. මෝල්ටෝස් = ග්ලූකෝස් + ග්ලූකෝස්\n2. සුක්‍රෝස් = ග්ලූකෝස් + ෆෲක්ටෝස්\n3. ලැක්ටෝස් = ග්ලූකෝස් + ගැලැක්ටෝස්", "ග්ලයිකොසයිඩික බන්ධන මඟින් මොනොසැකරයිඩ 2ක් එක්වේ.", "අණුක සූත්‍රය C₁₂H₂₂O₁₁ වේ"),
        FlashcardContent("පොලිසැකරයිඩ සඳහා උදාහරණ 3ක් සහ ඒවායේ කාර්යයන් දක්වන්න.", "1. පිෂ්ඨය (ශාකවල සංචිත ආහාරය)\n2. ග්ලයිකොජන් (සතුන්ගේ සංචිත ආහාරය - අක්මාවේ)\n3. සෙලියුලෝස් (ශාක සෛල බිත්තියේ ව්‍යුහාත්මක සංඝටකය)", "පොලිසැකරයිඩ ජලයේ අද්‍රාව්‍ය වන අතර පැණි රස නැත.", "(C₆H₁₀O₅)ₙ"),
        FlashcardContent("සිරුරේ තයිරොයිඩ් ග්‍රන්ථිය මඟින් නිපදවන හෝමෝනය සහ එහි කාර්යය කුමක්ද?", "තයිරොක්සින් (Thyroxine) හෝමෝනය. මූලික පරිවෘත්තීය සීඝ්‍රතාවය (BMR) සහ කායික/මානසික වර්ධනය පාලනය කරයි.", "අයඩින් ඌනතාවය තයිරොක්සින් නිෂ්පාදනය අඩාල වීමට සෘජුවම හේතු වේ.", "BMR පාලනය කරයි")
      ),
      2 to listOf( // පදාර්ථයේ ව්‍යුහය & ආවර්තිතා වගුව
        FlashcardContent("පරමාණුවක න්‍යෂ්ටියේ අඩංගු උප පරමාණුක අංශු 2 මොනවාද?", "ප්‍රෝටෝන (ධන ආරෝපිත) සහ නියුට්‍රෝන (උදාසීන ආරෝපිත).", "ඉලෙක්ට්‍රෝන (සෘණ ආරෝපිත) න්‍යෂ්ටිය වටා ශක්ති මට්ටම්වල භ්‍රමණය වේ.", "න්‍යෂ්ටික ස්කන්ධය = ප්‍රෝටෝන + නියුට්‍රෝන"),
        FlashcardContent("පරමාණුක ක්‍රමාංකය (Z) සහ ස්කන්ධ ක්‍රමාංකය (A) අර්ථ දක්වන්න.", "Z = පරමාණුවක න්‍යෂ්ටියේ ඇති ප්‍රෝටෝන සංඛ්‍යාව.\nA = න්‍යෂ්ටියේ ඇති ප්‍රෝටෝන සහ නියුට්‍රෝන සංඛ්‍යාවල එකතුව.", "නියුට්‍රෝන ගණන n = A - Z වේ.", "A = Z + n"),
        FlashcardContent("සමස්ථානික (Isotopes) යනු මොනවාද? උදාහරණයක් දෙන්න.", "පරමාණුක ක්‍රමාංකය (Z) සමාන නමුත් ස්කන්ධ ක්‍රමාංකය (A) වෙනස් එකම මූලද්‍රව්‍යයේ පරමාණු.", "හයිඩ්‍රජන් සමස්ථානික 3: ප්‍රෝටියම් (¹H), ඩියුටීරියම් (²H), ට්‍රිටියම් (³H).", "කාබන්: ¹²C, ¹³C, ¹⁴C"),
        FlashcardContent("සෝඩියම් (Na - 11) සහ ක්ලෝරීන් (Cl - 17) පරමාණුවල ඉලෙක්ට්‍රෝන වින්‍යාස ලියන්න.", "Na (11): 2, 8, 1\nCl (17): 2, 8, 7", "පළමු කවචයට 2ක්, දෙවන කවචයට 8ක්, තෙවන කවචයට 8ක් උපරිම වශයෙන් පිරවිය හැක.", "2n² සූත්‍රය අනුව උපරිම ධාරිතාව තීරණය වේ"),
        FlashcardContent("අයනික බන්ධනයක් (Ionic bond) සෑදෙන ආකාරය පැහැදිලි කරන්න.", "ලෝහ පරමාණුවක් ඉලෙක්ට්‍රෝන පිටකර කැටායනයක් (ධන) ද, අලෝහ පරමාණුවක් එම ඉලෙක්ට්‍රෝන ලබාගෙන ඇනායනයක් (සෘණ) ද සාදා ඒවා අතර විද්‍යුත් ස්ථිතික ආකර්ෂණයෙන් සෑදේ.", "උදා: Na⁺ + Cl⁻ → NaCl (සෝඩියම් ක්ලෝරයිඩ්).", "ලෝහ + අලෝහ = අයනික"),
        FlashcardContent("සහසංයුජ බන්ධනයක් (Covalent bond) සෑදෙන්නේ කෙසේද?", "අලෝහ පරමාණු දෙකක් අතර ඉලෙක්ට්‍රෝන යුගල හවුලේ තබා ගැනීමෙන් අෂ්ටක වින්‍යාසය ලබා ගනිමින් සෑදේ.", "උදා: H₂O (තනි බන්ධන 2), O₂ (ද්විත්ව බන්ධනයක්), N₂ (ත්‍රිත්ව බන්ධනයක්).", "අලෝහ + අලෝහ = සහසංයුජ"),
        FlashcardContent("ආවර්තිතා වගුවේ කාණ්ඩයක් (Group) ඔස්සේ පහළට යනවිට පරමාණුක අරය වෙනස් වන්නේ කෙසේද?", "නව ශක්ති මට්ටම් එකතු වීම නිසා කාණ්ඩයක් ඔස්සේ පහළට යන විට පරමාණුක අරය ක්‍රමයෙන් විශාල වේ.", "මේ නිසා පිටත ඉලෙක්ට්‍රෝන පහසුවෙන් ඉවත් කළ හැකි වී ලෝහක ගුණය වැඩි වේ.", "කාණ්ඩයේ පහළට: අරය වැඩි වේ"),
        FlashcardContent("ආවර්තයක් ඔස්සේ වමේ සිට දකුණට යනවිට ප්‍රථම අයනීකරණ ශක්තිය වෙනස් වන්නේ ඇයි?", "න්‍යෂ්ටික ආරෝපණය වැඩිවීම සහ පරමාණුක අරය අඩුවීම නිසා ඉලෙක්ට්‍රෝන තදින් බැඳී තිබීමෙන් අයනීකරණ ශක්තිය වැඩි වේ.", "අයනීකරණ ශක්තිය යනු වායුමය පරමාණුවකින් බාහිරතම ඉලෙක්ට්‍රෝනය ඉවත් කිරීමට අවශ්‍ය අවම ශක්තියයි.", "ආවර්තයේ දකුණට: අයනීකරණ ශක්තිය වැඩි වේ"),
        FlashcardContent("උච්ච වායුවල (Noble gases - VIII කාණ්ඩය) රසායනික අක්‍රියතාවයට හේතුව කුමක්ද?", "බාහිරතම ශක්ති මට්ටම උපරිම ඉලෙක්ට්‍රෝන සංඛ්‍යාවෙන් සම්පූර්ණ වී (අෂ්ටක වින්‍යාසය ns² np⁶) ස්ථායීව පැවතීම.", "හීලියම් (He), නියොන් (Ne), ආගන් (Ar) උදාහරණ වේ.", "ස්ථාවර අෂ්ටක වින්‍යාසය"),
        FlashcardContent("විද්‍යුත් සෘණතාව (Electronegativity) වැඩිම මූලද්‍රව්‍යය කුමක්ද? එහි අර්ථය කුමක්ද?", "ෆ්ලෝරීන් (F). සහසංයුජ බන්ධනයක ඉලෙක්ට්‍රෝන තමා දෙසට ඇද ගැනීමේ සාපේක්ෂ හැකියාවයි.", "පෝලිං පරිමාණයේ ෆ්ලෝරීන් අගය 4.0 කි.", "F > O > Cl > N"),
        FlashcardContent("අයනික සංයෝග සහ සහසංයුජ සංයෝගවල ද්‍රවාංක සංසන්දනය කරන්න.", "අයනික සංයෝග: ප්‍රබල විද්‍යුත් ස්ථිතික ආකර්ෂණ බල නිසා ඉතා ඉහළ ද්‍රවාංක හා තාපාංක ඇත.\nසහසංයුජ සංයෝග: දුබල අන්තර් අණුක බල නිසා සාපේක්ෂව අඩු ද්‍රවාංක ඇත.", "NaCl ද්‍රවාංකය 801°C වන අතර ග්ලූකෝස් ද්‍රවාංකය 146°C පමණ වේ.", "අයනික > සහසංයුජ ද්‍රවාංකය"),
        FlashcardContent("විද්‍යුත් සන්නායකතාව අනුව අයනික සංයෝග හැසිරෙන්නේ කෙසේද?", "ඝන අවස්ථාවේදී අයන නිදහස් නොවන බැවින් විදුලිය සන්නයනය නොකරයි. විලයනය වූ විට හෝ ජලීය ද්‍රාවණවලදී විදුලිය හොඳින් සන්නයනය කරයි.", "නිදහස් අයන පැවතීම විද්‍යුත් සන්නායකතාවට හේතුවයි.", "ද්‍රාවිත/ජලීය: සන්නායකයි"),
        FlashcardContent("ලෝහක බන්ධනය (Metallic bond) යනු කුමක්ද?", "ස්ථාවර ලෝහ කැටායන ජාලයක් සහ ඒ වටා නිදහසේ චලනය වන විලෝකනය වූ ඉලෙක්ට්‍රෝන මුහුද අතර ඇති ආකර්ෂණයයි.", "ලෝහවල විද්‍යුත් හා තාප සන්නායකතාව, ආහන්‍යතාව හා තන්‍යතාවයට හේතුව මෙයයි.", "විලෝකිත ඉලෙක්ට්‍රෝන මුහුද"),
        FlashcardContent("I කාණ්ඩයේ ක්ෂාර ලෝහ ජලය සමග ප්‍රතික්‍රියා කළ විට පිටවන වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂) වායුව පිටවන අතර ක්ෂාරීය ද්‍රාවණයක් (ලෝහ හයිඩ්‍රොක්සයිඩ්) සාදයි.", "2Na + 2H₂O → 2NaOH + H₂↑. හයිඩ්‍රජන් 'පොප්' හඬින් දැවේ.", "H₂ වායුව"),
        FlashcardContent("ද්වි පරමාණුක අණු (Diatomic molecules) සඳහා උදාහරණ 4ක් දෙන්න.", "හයිඩ්‍රජන් (H₂), ඔක්සිජන් (O₂), නයිට්‍රජන් (N₂), ක්ලෝරීන් (Cl₂).", "පරමාණු දෙකක් එක්වී අණුවක් සෑදීම ද්වි පරමාණුක නම් වේ.", "H₂, O₂, N₂, F₂, Cl₂, Br₂, I₂"),
        FlashcardContent("ලුවිස් තිත්-කතිර සටහනකින් (Lewis Structure) නිරූපණය කරන්නේ කුමක්ද?", "පරමාණුවල බාහිරතම ශක්ති මට්ටමේ (සංයුජතා කවචයේ) ඇති ඉලෙක්ට්‍රෝන පමණක් තිත් හෝ කතිර මඟින් දැක්වීම.", "බන්ධන ඉලෙක්ට්‍රෝන යුගල සහ එකසර ඉලෙක්ට්‍රෝන යුගල පැහැදිලිව පෙන්වයි.", "සංයුජතා ඉලෙක්ට්‍රෝන නිරූපණය"),
        FlashcardContent("හයිඩ්‍රජන් බන්ධනයක් (Hydrogen bond) ඇතිවන්නේ කුමන පරමාණු අතරද?", "විද්‍යුත් සෘණතාව ඉතා වැඩි කුඩා පරමාණුවක් (F, O, N) සමග බැඳී ඇති හයිඩ්‍රජන් පරමාණුවක් සහ වෙනත් එවැනි අණුවක් අතර.", "ජලයේ අසාමාන්‍ය ලෙස ඉහළ තාපාංකයට (100°C) ප්‍රධාන හේතුව හයිඩ්‍රජන් බන්ධනයි.", "H...F, H...O, H...N"),
        FlashcardContent("ආවර්තිතා වගුවේ ප්‍රථම මූලද්‍රව්‍ය 20න් උභයගුණී ඔක්සයිඩ සාදන මූලද්‍රව්‍යය කුමක්ද?", "ඇලුමිනියම් (Al). ඇලුමිනියම් ඔක්සයිඩ් (Al₂O₃) අම්ල මෙන්ම භෂ්ම සමග ද ප්‍රතික්‍රියා කර ලවණ සහ ජලය සාදයි.", "අම්ලයක් හමුවේ භෂ්මයක් ලෙසද, භෂ්මයක් හමුවේ අම්ලයක් ලෙසද හැසිරේ.", "Al₂O₃ = උභයගුණී"),
        FlashcardContent("කාබන්හි ප්‍රධාන බහුරූපී (Allotropes) ආකාර 3 මොනවාද?", "1. දියමන්ති (Diamond - අතිශය දැඩි, විදුලිය නොසන්නයයි)\n2. මිනිරන්/ග්‍රැෆයිට් (Graphite - සන්නායකයි, ලිහිසි ද්‍රව්‍යයකි)\n3. ෆුලරීන් (Fullerene / Buckyballs)", "එකම මූලද්‍රව්‍යය විවිධ භෞතික ව්‍යුහයන්ගෙන් පැවතීම බහුරූපතාවයි.", "කාබන් බහුරූපී ආකාර"),
        FlashcardContent("කැටායනයක් සහ ඇනායනයක් ප්‍රමාණයෙන් මව් පරමාණුවට වඩා වෙනස් වන්නේ ඇයි?", "කැටායනය: ඉලෙක්ට්‍රෝන අහිමි වී න්‍යෂ්ටික ආකර්ෂණය වැඩිවන බැවින් මව් පරමාණුවට වඩා කුඩා වේ.\nඇනායනය: ඉලෙක්ට්‍රෝන එකතු වී විකර්ෂණය වැඩිවන බැවින් මව් පරමාණුවට වඩා විශාල වේ.", "Na⁺ < Na වන අතර Cl⁻ > Cl වේ.", "කැටායන කුඩායි, ඇනායන විශාලයි")
