  private fun getMathCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val mathSets = mapOf(
      1 to listOf( // වීජ ගණිතය, සාධක & ප්‍රකාශන
        FlashcardContent("වර්ග දෙකක අන්තරය සාධක කඩන්නේ කෙසේද?", "a² - b² = (a - b)(a + b)", "උදා: 4x² - 25 = (2x - 5)(2x + 5). O/L පත්‍රයේ නිතරම ලැබෙන ලකුණු 2ක ප්‍රශ්නයකි.", "a² - b² = (a - b)(a + b)"),
        FlashcardContent("පූර්ණ වර්ග ත්‍රිපද ප්‍රකාශන ප්‍රසාරණය කුමක්ද?", "(a + b)² = a² + 2ab + b²\n(a - b)² = a² - 2ab + b²", "මැද පදයේ දෙගුණය ලකුණ සහිතව තැබීමට සැලකිලිමත් වන්න.", "(a ± b)² = a² ± 2ab + b²"),
        FlashcardContent("වර්ගජ සමීකරණ විසඳීමේ සාමාන්‍ය සූත්‍රය ලියන්න.", "x = [-b ± √(b² - 4ac)] / (2a)", "ax² + bx + c = 0 ආකාරයෙන් සකස් කරගත් පසු a, b, c ආදේශ කරන්න.", "Quadratic Formula"),
        FlashcardContent("වර්ගජ සමීකරණයක විවේචකය Δ = b² - 4ac මඟින් මූලවල ස්වභාවය පවසන්නේ කෙසේද?", "Δ > 0 නම්: එකිනෙකට වෙනස් තාත්වික මූල 2කි.\nΔ = 0 නම්: සමාන තාත්වික මූල 2කි.\nΔ < 0 නම්: තාත්වික මූල නොපවතී.", "මූල සමාන වන විට b² = 4ac සබඳතාව බහුලව අසයි.", "විවේචකය (Discriminant)"),
        FlashcardContent("වීජීය භාග එකතු කිරීමේදී සහ අඩු කිරීමේදී පළමු පියවර කුමක්ද?", "හරයන් සාධක කඩා ඒවායේ කුඩාම පොදු ගුණාකාරය (කු.පො.ගු.) සෙවීම.", "හරය සමාන කළ පසු පමණක් ලවයන් සුළු කළ හැක.", "පොදු හරය = කු.පො.ගු."),
        FlashcardContent("ඝන ප්‍රකාශන ප්‍රසාරණ සූත්‍ර 2 ලියන්න.", "a³ + b³ = (a + b)(a² - ab + b²)\na³ - b³ = (a - b)(a² + ab + b²)", "දෙවන වරහනේ මැද පදයේ ලකුණ පළමු වරහනේ ලකුණට විරුද්ධ වේ.", "Sum & Difference of Cubes"),
        FlashcardContent("ලඝුගණක මූලික ගුණිත නීතිය සහ බෙදීම් නීතිය ලියන්න.", "logₐ(xy) = logₐ x + logₐ y\nlogₐ(x/y) = logₐ x - logₐ y", "භූමිකාව සමාන ලඝුගණක අතර පමණක් මෙම නීති ක්‍රියාත්මක වේ.", "log(xy) = log x + log y"),
        FlashcardContent("ලඝුගණක බල නීතිය කුමක්ද?", "logₐ(xᵏ) = k · logₐ x", "උදා: log₁₀(10³) = 3 log₁₀ 10 = 3 × 1 = 3.", "log(xᵏ) = k log x"),
        FlashcardContent("දර්ශක නීති: aᵐ × aⁿ සහ aᵐ ÷ aⁿ සූත්‍ර මොනවාද?", "aᵐ × aⁿ = aᵐ⁺ⁿ (පාද සමාන විට ගුණ කිරීමේදී දර්ශක එකතු වේ).\naᵐ ÷ aⁿ = aᵐ⁻ⁿ (පාද සමාන විට බෙදීමේදී දර්ශක අඩු වේ).", "ඕනෑම සංඛ්‍යාවක ශුන්‍ය බලය 1 වේ (a⁰ = 1).", "aᵐ · aⁿ = aᵐ⁺ⁿ"),
        FlashcardContent("සෘණ දර්ශක ධන කරන්නේ කෙසේද? (a⁻ⁿ)", "a⁻ⁿ = 1 / aⁿ", "උදා: 2⁻³ = 1 / 2³ = 1/8. භාගයක හරයේ ඇති සෘණ දර්ශකය ලවයට ගෙන ඒමෙන් ධන වේ.", "a⁻ⁿ = 1/aⁿ"),
        FlashcardContent("භාගික දර්ශක සූත්‍රය a^(m/n) කරණියක් ලෙස ලියන්නේ කෙසේද?", "a^(m/n) = ⁿ√(aᵐ) හෝ (ⁿ√a)ᵐ", "උදා: 8^(2/3) = (³√8)² = 2² = 4.", "Fractional Indices"),
        FlashcardContent("සමගාමී සමීකරණ විසඳීමේ ප්‍රධාන ක්‍රම 2 මොනවාද?", "1. එක් විචල්‍යයක් ඉවත් කිරීමේ ක්‍රමය (Elimination).\n2. ආදේශ කිරීමේ ක්‍රමය (Substitution).", "සංගුණක සමාන කර ලකුණු එක සමාන නම් අඩු කර, ලකුණු ප්‍රතිවිරුද්ධ නම් එකතු කරන්න.", "Simultaneous Equations"),
        FlashcardContent("අසමානතාවයක දෙපස සෘණ (-) සංඛ්‍යාවකින් ගුණ කළ විට හෝ බෙදූ විට සිදුවන්නේ කුමක්ද?", "අසමානතා ලකුණ අනිවාර්යයෙන්ම ප්‍රතිවිරුද්ධ දිශාවට හැරේ (< ලකුණ > බවට ද, > ලකුණ < බවට ද පත්වේ).", "උදා: -2x < 6 නම්, -2 න් බෙදූ විට x > -3 වේ. විභාගයේදී නිතර ලකුණු කැපෙන තැනකි.", "සෘණ ලකුණින් බෙදීමේදී දිශාව මාරු වේ"),
        FlashcardContent("ax² + bx + c ත්‍රිපද ප්‍රකාශනයක සාධක සෙවීමේ මූලධර්මය කුමක්ද?", "ගුණිතය a × c ද, එකතුව මැද පදය b ද වන පරිදි සංඛ්‍යා දෙකක් සොයා මැද පදය වෙන් කිරීම.", "උදා: x² + 5x + 6 හි ගුණිතය 6, එකතුව 5 වන සංඛ්‍යා 2 සහ 3 වේ → (x + 2)(x + 3).", "මැද පදය වෙන් කිරීම"),
        FlashcardContent("log₁₀ 1 සහ log₁₀ 10 හි අගයන් මොනවාද?", "log₁₀ 1 = 0\nlog₁₀ 10 = 1", "ඕනෑම පාදයකට 1 හි ලඝුගණකය සැමවිටම 0 වේ.", "log 1 = 0, log 10 = 1"),
        FlashcardContent("ලඝුගණක වගුව භාවිතයෙන් සංඛ්‍යාවක ලඝුගණකය සෙවීමේ කොටස් 2 මොනවාද?", "1. පූර්ණාංශය (Characteristic): සංඛ්‍යාවේ විශාලත්වය අනුව නීති මඟින් ලියන කොටස.\n2. දශමාංශය (Mantissa): ලඝුගණක වගුවෙන් බලන ධන දශම කොටස.", "1ට වඩා කුඩා සංඛ්‍යාවල පූර්ණාංශය සෘණ (බාර්) අගයකි. උදා: 0.05 හි පූර්ණාංශය 2̄ වේ.", "Characteristic + Mantissa"),
        FlashcardContent("ප්‍රතිලඝුගණකය (Antilog) බලන්නේ ලඝුගණකයේ කුමන කොටසින්ද?", "දශමාංශයෙන් (Mantissa) පමණි. ලැබෙන පිළිතුරට දශම තිත තබන්නේ පූර්ණාංශයේ අගය පදනම් කරගෙනයි.", "පූර්ණාංශය 2 නම් පිළිතුරේ දශම තිතට පෙර ඉලක්කම් 3ක් තිබිය යුතුය.", "Antilog from Mantissa"),
        FlashcardContent("විද්‍යාත්මක අංකනය (Scientific Notation) යනු කුමක්ද?", "A × 10ⁿ ආකාරයෙන් ලිවීමයි (මෙහි 1 ≤ A < 10 වන අතර n නිඛිලයකි).", "උදා: 45,000 = 4.5 × 10⁴. 0.0032 = 3.2 × 10⁻³.", "1 ≤ A < 10"),
        FlashcardContent("වර්ගපූර්ණයෙන් (Completing the Square) x² + 6x පූර්ණ වර්ගයක් කරන්නේ කෙසේද?", "x හි සංගුණකයෙන් අඩක වර්ගය එකතු කිරීමෙනි: (6/2)² = 3² = 9 එකතු කිරීමෙන් (x + 3)² ලැබේ.", "සැමවිටම x² හි සංගුණකය 1 කරගත් පසු මෙම පියවර අනුගමනය කරන්න.", "(b/2)² එකතු කිරීම"),
        FlashcardContent("ඝන දෙකක ඓක්‍යය සහ අන්තරය සූත්‍ර යොදාගැනීමේ උදාහරණයක් දක්වන්න.", "x³ + 8 = x³ + 2³ = (x + 2)(x² - 2x + 4)\nx³ - 27 = x³ - 3³ = (x - 3)(x² + 3x + 9)", "දෙවන වරහනේ 2ab නොව ab පමණක් එන බව මතක තබාගන්න.", "(a ± b)(a² ∓ ab + b²)")
      )
    )

    val list = mathSets[setNum] ?: (1..20).map { idx ->
      FlashcardContent(
        question = "$theme පාඩමට අදාළ O/L ගණිත ප්‍රමේයය හෝ සූත්‍රය අංක $idx කුමක්ද?",
        answer = "ගණිත ගැටලුව විසඳීමේදී දත්ත පෙළගැස්වීම, නිවැරදි සූත්‍රය තෝරාගැනීම, අගයන් ආදේශය සහ පියවරෙන් පියවර සුළු කිරීම අනුගමනය කරන්න.",
        tip = "විභාග ඉඟිය: අවසාන පිළිතුරට පෙර පියවර සඳහා ලකුණු 70%ක් පමණ හිමි වේ.",
        fact = "ගණිතය • ශ්‍රේණිය $grade • කාණ්ඩය $setNum"
      )
    }

    return list[(cardInSet - 1) % list.size]
  }

  // --------------------------------------------------------------------------
  // 3. HISTORY FLASHCARDS
  // --------------------------------------------------------------------------
  private fun getHistoryCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val items = listOf(
      FlashcardContent("පළමුවන විජයබාහු රජු අගනුවර ලෙස පොළොන්නරුව තෝරා ගැනීමට ප්‍රධාන හේතු මොනවාද?", "1. චෝල ආක්‍රමණවලින් ආරක්ෂාවීම (මහවැලි ගඟ ස්වභාවික පවුරක් වීම).\n2. රුහුණට ඉක්මනින් සේන්දු විය හැකි වීම.\n3. ගෝකණ්ණ (ත්‍රිකුණාමල) වරාය පාලනය පහසුවීම.", "ක්‍රි.ව. 1070 දී චෝලයින් පරදා අනුරාධපුරය මුදාගත්තේය.", "පොළොන්නරු යුගය ආරම්භය"),
      FlashcardContent("මහා පරාක්‍රමබාහු රජුගේ ප්‍රධාන කෘෂිකාර්මික නිර්මාණය කුමක්ද?", "පරාක්‍රම සමුද්‍රය නිර්මාණය කිරීම (තෝපාවැව, දුඹුටුලු වැව, එරබදු වැව එක්කර).", "\"අහසින් වැටෙන එකදු දිය බිඳක්වත් මිනිසාගේ ප්‍රයෝජනයට නොගෙන මුහුදට ගලා යාමට ඉඩ නොදිය යුතුය\".", "පොළොන්නරු ස්වර්ණමය යුගය"),
      FlashcardContent("උඩරට ගිවිසුම අත්සන් කළේ කවදාද? කා අතරද?", "1815 මාර්තු 02 දින. බ්‍රිතාන්‍ය ආණ්ඩුකාර රොබට් බ්‍රවුන්රිග් සහ ඇහැලේපොළ, මිල්ලව ඇතුළු උඩරට ප්‍රධානීන් අතර.", "ශ්‍රී වික්‍රම රාජසිංහ රජු බලයෙන් පහකර ලක්දිව සම්පූර්ණයෙන්ම බ්‍රිතාන්‍ය කිරීටයට යටත් විය.", "1815 මාර්තු 02"),
