  private fun getIctCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val items = listOf(
      FlashcardContent("RAM සහ ROM අතර ප්‍රධාන වෙනස්කම් මොනවාද?", "RAM: නශ්වර මතකයකි (විදුලිය නැතිවිට මැකේ), කියවීම හා ලිවීම කළ හැක.\nROM: අනශ්වර මතකයකි (දත්ත ස්ථිරයි), කියවීම පමණක් කළ හැක (BIOS ඇත).", "RAM ප්‍රමාණය වැඩිවීමෙන් Multitasking වේගවත් වේ.", "RAM (Volatile) vs ROM"),
      FlashcardContent("ද්විමය (Binary) සංඛ්‍යා පද්ධතියේ පාදය සහ අංක මොනවාද?", "පාදය 2 වේ. භාවිත වන සංකේත 0 සහ 1 පමණි.", "පරිගණකය ක්‍රියාත්මක වන්නේ ඩිජිටල් ද්විමය සංඥා මඟිනි.", "Base 2: 0, 1"),
      FlashcardContent("ප්‍රධාන තාර්කික ද්වාර (Logic Gates) 3 සහ ඒවායේ ක්‍රියාකාරිත්වය කුමක්ද?", "AND: සියලු ආදාන 1 විට පමණක් ප්‍රතිදානය 1 වේ.\nOR: ඕනෑම ආදානයක් 1 විට ප්‍රතිදානය 1 වේ.\nNOT: ආදානය ප්‍රතිවිරුද්ධ කරයි (0 නම් 1, 1 නම් 0).", "සත්‍යතා වගු (Truth Tables) මඟින් ප්‍රතිදානය ගණනය කරයි.", "AND, OR, NOT"),
      FlashcardContent("IP ලිපිනයක් යනු කුමක්ද? IPv4 සහ IPv6 අතර වෙනස කුමක්ද?", "ජාලයක ඇති උපාංගයක් අනන්‍යව හඳුනාගන්නා අංකයයි. IPv4 හි බිට් 32ක් ද IPv6 හි බිට් 128ක් ද අඩංගු වේ.", "IPv4 ලිපිනයක් තිත් වලින් වෙන් කළ දශම අංක 4කින් ලියයි (උදා: 192.168.1.1).", "IPv4 (32 bit), IPv6 (128 bit)"),
      FlashcardContent("පද්ධති සංවර්ධන ජීවන චක්‍රයේ (SDLC) ප්‍රධාන අදියර මොනවාද?", "1. අවශ්‍යතා හඳුනාගැනීම\n2. පද්ධති සැලසුම්කරණය\n3. කේතකරණය/ක්‍රමලේඛනය\n4. පරීක්ෂා කිරීම\n5. ස්ථාපනය සහ නඩත්තුව", "ක්‍රමානුකූලව මෘදුකාංගයක් නිර්මාණය කිරීමේ පියවරයි.", "SDLC අදියර 5"),
      FlashcardContent("HTML හි හයිපර්ලින්ක් (Hyperlink) සහ පින්තූරයක් (Image) ඇතුළත් කරන ටැග මොනවාද?", "හයිපර්ලින්ක්: <a href=\"URL\">ලින්ක් එකේ නම</a>\nපින්තූරය: <img src=\"image.jpg\" alt=\"විස්තරය\">", "HTML වෙබ් පිටුවල අන්තර්ගතය සැකසීමට යොදාගනී.", "<a> සහ <img> ටැග")
    )
    val item = items[(setNum * 2 + cardInSet - 1) % items.size]
    return item
  }

  // --------------------------------------------------------------------------
  // 9. ENGLISH FLASHCARDS
  // --------------------------------------------------------------------------
  private fun getEnglishCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val items = listOf(
      FlashcardContent("How is the Passive Voice formed in Simple Present and Simple Past?", "Simple Present: am/is/are + V3 (e.g. Rice is grown by farmers).\nSimple Past: was/were + V3 (e.g. The poem was written by Wordsworth).", "Always identify the direct object and make it the grammatical subject.", "Subject + be + V3 + by + Agent"),
      FlashcardContent("What are the 3 Conditional Sentences structures?", "Type 1: If + Simple Present, will + V1 (e.g. If it rains, we will cancel the match).\nType 2: If + Simple Past, would + V1 (e.g. If I had wings, I would fly).\nType 3: If + Past Perfect, would have + V3 (e.g. If she had studied, she would have passed).", "Type 2 uses 'were' for all pronouns: If I were you...", "Conditionals (Type 1, 2, 3)"),
      FlashcardContent("What are the formal expressions for describing Bar Charts and Pie Charts?", "1. 'The chart illustrates the percentage of...'\n2. '...witnessed a gradual upward trend from... to...'\n3. 'A sharp decline was observed in...'\n4. 'The majority accounted for...'", "Crucial for G.C.E. O/L Paper II Question 14 (Description of Visuals).", "Chart Vocabulary"),
      FlashcardContent("How do you convert Direct Speech to Indirect Speech?", "Present tense changes to Past tense. Pronouns and time adverbs shift: now → then, today → that day, tomorrow → the next day, yesterday → the day before.", "e.g. He said, 'I am tired' → He said that he was tired.", "Reported Speech"),
      FlashcardContent("What is the difference between 'Since' and 'For' in Present Perfect tense?", "'Since' refers to a specific starting point in time (e.g. since 2010, since Monday).\n'For' refers to a duration/period of time (e.g. for five years, for two hours).", "I have lived here since 2015. / I have lived here for 9 years.", "Since (point) vs For (duration)"),
      FlashcardContent("What are the key components of an Official Formal Letter?", "1. Sender's Address & Date\n2. Receiver's Designation & Address\n3. Salutation (Dear Sir/Madam)\n4. Heading/Topic\n5. Body Paragraphs (Clear purpose)\n6. Formal Close (Yours faithfully) & Signature", "Essential for O/L Paper II formal writing question.", "Formal Letter Format")
    )
    val item = items[(setNum * 2 + cardInSet - 1) % items.size]
    return item
  }

  // --------------------------------------------------------------------------
  // 10. GEOGRAPHY FLASHCARDS
  // --------------------------------------------------------------------------
  private fun getGeographyCard(grade: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    val items = listOf(
      FlashcardContent("ශ්‍රී ලංකාවේ භූ විෂමතා තලා 3 මොනවාද?", "1. වෙරළබඩ තැනිතලාව (මුහුදු මට්ටමේ සිට මීටර් 30 දක්වා)\n2. අභ්‍යන්තර සානුව/මැද කඳුකර තැනිතලාව (මීටර් 30 - 300)\n3. මධ්‍යම කඳුකරය (මීටර් 300ට වැඩි)", "පිදුරුතලාගල (මීටර් 2524) මධ්‍යම කඳුකරයේ පිහිටි උසම ස්ථානයයි.", "තලා 3ක භූ විෂමතාව"),
      FlashcardContent("ශ්‍රී ලංකාවට වර්ෂාව ලැබෙන ප්‍රධාන ක්‍රම 3 මොනවාද?", "1. නිරිතදිග මෝසම (මැයි - සැප්තැම්බර්)\n2. ඊසානදිග මෝසම (දෙසැම්බර් - පෙබරවාරි)\n3. සංවහන වැසි (අන්තර් මෝසම් සමයන්හි - අප්‍රේල්/ඔක්තෝබර්)", "සංවහන වැසි පස්වරුවේ අකුණු සහිතව ඇදහැලෙයි.", "මෝසම් & සංවහන වැසි"),
      FlashcardContent("භූ ලක්ෂණ සිතියමක (Topographical Map) සමෝච්ච රේඛා (Contour lines) ළඟින් ළඟින් පිහිටීමේ තේරුම කුමක්ද?", "භූමියේ බෑවුම අධික (කಡಿದු බෑවුමක්) බව පෙන්නුම් කරයි. සමෝච්ච රේඛා ඈතින් පිහිටීමෙන් මෘදු බෑවුමක් පෙන්නුම් කරයි.", "සමෝච්ච රේඛා යනු මුහුදු මට්ටමේ සිට සමාන උසකින් යුත් ලක්ෂ්‍ය යා කර අඳින රේඛා වේ.", "සමෝච්ච රේඛා"),
      FlashcardContent("පෘථිවියේ අභ්‍යන්තර ස්ථර 3 මොනවාද?", "1. කබොල (Crust - පිටතම ඝන ස්ථරය)\n2. ප්‍රාවරණය (Mantle - මැග්මා සහිත මැද ස්ථරය)\n3. හරය (Core - අභ්‍යන්තර හා බාහිර හරය, යකඩ හා නිකල් බහුලයි)", "භූ තැටි චලනය සිදුවන්නේ ප්‍රාවරණය මත පාවෙන කබොල කොටස්වලිනි.", "කබොල, ප්‍රාවරණය, හරය")
    )
    val item = items[(setNum * 2 + cardInSet - 1) % items.size]
    return item
  }

  // --------------------------------------------------------------------------
  // GENERAL FALLBACK
  // --------------------------------------------------------------------------
  private fun getGeneralCard(grade: String, subject: String, setNum: Int, cardInSet: Int, theme: String): FlashcardContent {
    return FlashcardContent(
      question = "$grade ශ්‍රේණිය $subject: $theme ඒකකයේ ප්‍රධාන කරුණ අංක $cardInSet කුමක්ද?",
      answer = "$theme ඒකකයේ නිර්වචන, න්‍යායයන් සහ විභාග ප්‍රශ්නෝත්තර සවිස්තරව මතක තබාගන්න. O/L විභාගයේදී මෙම ඒකකයෙන් අනිවාර්ය ප්‍රශ්නයක් විමසනු ලැබේ.",
      tip = "විභාග ඉඟිය: මෙම ප්‍රශ්නයට අදාළ නිවැරදි තාක්ෂණික පද භාවිත කරමින් පිළිතුර කෙටියෙන් සටහන් කරන්න.",
      fact = "$subject • $grade ශ්‍රේණිය • කාණ්ඩය $setNum"
    )
  }
}
